/bin/zsh -lc "python3 -c 'import json,re; u=json.load(open(\"source_cache_3.json\"))[\"units\"]; specs=[(\"sure\",797,2700),(\"team\",812,900),(\"part-time\",581,260),(\"ever\",283,1800),(\"family\",297,1900),(\"keep\",444,3500),(\"might\",506,1900),(\"please\",607,1100)];
for w,p,n in specs:
 t=u[p-1]; m=re.search(r\"\\n\"+re.escape(w)+r\"[ \\[]\",t); print(json.dumps({\"word\":w,\"page\":p,\"text\":t[m.start()+1:m.start()+n] if m else \"heading not found\"},ensure_ascii=False))'"

